rules.script:
// Pass it on: the ball that hit stops dead and lights up; the woken ball carries on at a steady speed.
const [m, w] = [ctx.other, ctx.ball];
m.frozen = true;
ctx.state.lit = (ctx.state.lit ?? 0) + (w.id > 0 && !ctx.state[w.id] ? 1 : 0);
ctx.state[w.id] = true;
w.color = m.color;
const s = Math.hypot(w.vx, w.vy) || 1;
w.vx = (w.vx / s) * 650;
w.vy = (w.vy / s) * 650;
if (ctx.state.lit % 7 === 0) w.color = ['#ff4d6d', '#ff9f1c', '#ffd23f', '#7cff6b', '#4dd4ff', '#c77dff'][ctx.rng.int(6)];
if (ctx.state.lit >= 49) ctx.world.end();
